head.script:
scwin.clickId;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        rdo_MKT_ID.setValue(js_market);
        if (js_market === '1' || js_market === '2') {
            panel_mkt.hide();
        }
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        await scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30330.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    // 업무구분초기화
    const sbmOptions = {
        id : "sbm_dts_business",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_business=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 진행사항 초기화
    const sbmOptions2 = {
        id : "sbm_dts_progress_state",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_progress_state=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_EDate.setValue(vCurDate); // 현재날짜

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
